<?php
require_once "config/auth.php"; require_login();$msg="";
if($_SERVER["REQUEST_METHOD"]==="POST" && current_role()==="Administrador"){$t=trim($_POST["titulo"]??"");$d=trim($_POST["descripcion"]??"");$f=$_POST["fecha"]??"";if($t&&$f){$s=$conn->prepare("INSERT INTO calendario(titulo,descripcion,fecha) VALUES(?,?,?)");$s->bind_param("sss",$t,$d,$f);$msg=$s->execute()?"Evento agregado.":"No se pudo guardar el evento.";}}
$rows=$conn->query("SELECT * FROM calendario ORDER BY fecha");include "includes/header.php";?>
<div class="mb-3"><span class="eyebrow">ACTIVIDADES INSTITUCIONALES</span><h2 class="fw-bold">Calendario escolar</h2></div><?php if($msg):?><div class="alert alert-info"><?=e($msg)?></div><?php endif;?>
<?php if(current_role()==="Administrador"):?><div class="card border-0 shadow-sm mb-4"><div class="card-body"><form method="post" class="row g-3"><div class="col-md-4"><label class="form-label">Título</label><input class="form-control" name="titulo" required></div><div class="col-md-5"><label class="form-label">Descripción</label><input class="form-control" name="descripcion"></div><div class="col-md-2"><label class="form-label">Fecha</label><input class="form-control" type="date" name="fecha" required></div><div class="col-md-1 d-flex align-items-end"><button class="btn btn-primary">Añadir</button></div></form></div></div><?php endif;?>
<div class="row g-3"><?php while($r=$rows->fetch_assoc()):?><div class="col-md-6 col-xl-4"><div class="card border-0 shadow-sm h-100"><div class="card-body"><span class="badge text-bg-primary"><?=e($r["fecha"])?></span><h5 class="fw-bold mt-3"><?=e($r["titulo"])?></h5><p class="text-secondary mb-0"><?=e($r["descripcion"])?></p></div></div></div><?php endwhile;?></div><?php include "includes/footer.php";?>
